void SegmentedLineClass::Prepare_LOD(CameraClass &view)
{
	NormalizedScreenArea = Get_Screen_Size(view);
	unsigned int current = LineRenderer.Get_Current_Subdivision_Level();
	if (current >= MaxSubdivisionLevels)
		current = MaxSubdivisionLevels;
	LineRenderer.Set_Current_Subdivision_Level(current);
}

// FUNCTION: BFME2 0x0015E4B0 size=33 name=?Increment_LOD@SegmentedLineClass@@UAEXXZ evidence=N:ledger
void SegmentedLineClass::Increment_LOD()
{
	unsigned int next = LineRenderer.Get_Current_Subdivision_Level() + 1;
	LineRenderer.Set_Current_Subdivision_Level(next < MaxSubdivisionLevels ? next : MaxSubdivisionLevels);
}

// FUNCTION: BFME2 0x0015E4E0 size=20 name=?Decrement_LOD@SegmentedLineClass@@UAEXXZ evidence=N:ledger
void SegmentedLineClass::Decrement_LOD()
{
	unsigned int level = LineRenderer.Get_Current_Subdivision_Level();
	if (level != 0)
		LineRenderer.Set_Current_Subdivision_Level(level - 1);
}

// FUNCTION: BFME2 0x0015E510 size=82 name=?Get_Value@SegmentedLineClass@@UBEMXZ evidence=N:ledger
float SegmentedLineClass::Get_Value() const
{
	// If we are at the minimum LOD, we must return AT_MIN_LOD.
	if (LineRenderer.Get_Current_Subdivision_Level() == 0) {
		return 3.4028235e38f;
	} else {
		float polycount = (float)Get_Num_Polys();
		float benefit_factor = 1.0f - (0.5f / (polycount * polycount));
		return (benefit_factor * NormalizedScreenArea) / Get_Cost();
	}
}

// FUNCTION: BFME2 0x0015E570 size=71 name=?Get_Post_Increment_Value@SegmentedLineClass@@UBEMXZ evidence=N:ledger
float SegmentedLineClass::Get_Post_Increment_Value() const
{
	if (LineRenderer.Get_Current_Subdivision_Level() == MaxSubdivisionLevels)
		return -1.0f;
	float polys = (float)Get_Num_Polys() * 2.0f;
	float benefit = (1.0f - 0.5f / (polys * polys)) * NormalizedScreenArea;
	return benefit / polys;
}

// FUNCTION: BFME2 0x0015E5C0 size=44 name=?Set_LOD_Level@SegmentedLineClass@@UAEXH@Z evidence=N:ledger
void SegmentedLineClass::Set_LOD_Level(int level)
{
	level = (level < 0) ? 0 : level;
	if (level >= (int)MaxSubdivisionLevels)
		LineRenderer.Set_Current_Subdivision_Level(MaxSubdivisionLevels);
	else
		LineRenderer.Set_Current_Subdivision_Level(level);
}

