// FUNCTION: BFME2 0x0015F100 size=104 name=?Set_Points@SegmentedLineClass@@QAEXIPAVVector3@@@Z evidence=N:ledger
void SegmentedLineClass::Set_Points(unsigned int num_points, Vector3 *locs)
{
	PointLocations.Delete_All();
	Invalidate_Cached_Bounding_Volumes();

	if (num_points >= 2 && locs != 0) {
		for (unsigned int n = 0; n < num_points; n++)
			PointLocations.Add(locs[n], num_points);
	}
}

