// FUNCTION: BFME2 0x0015F260 size=90 name=?Render@SegmentedLineClass@@UAEXAAVRenderInfoClass@@@Z evidence=N:ledger
void SegmentedLineClass::Render(RenderInfoClass &rinfo)
{
	if (Is_Not_Hidden_At_All() == false) {
		return;
	}

	unsigned int sort_level = 0;

	if (!WW3D::Is_Sorting_Enabled())
		sort_level = LineRenderer.Get_Shader().Guess_Sort_Level();

	if (WW3D::Are_Static_Sort_Lists_Enabled() && sort_level != 0) {

		WW3D::Add_To_Static_Sort_List(this, sort_level);

	}
	else
	{
		Render_Seg_Line(rinfo);
	}
}

// FUNCTION: BFME2 0x0015F2C0 size=596 name=?Cast_Ray@SegmentedLineClass@@UAE_NAAVRayCollisionTestClass@@@Z evidence=N:ledger
bool SegmentedLineClass::Cast_Ray(RayCollisionTestClass &raytest)
{
	if ((Get_Collision_Type() & raytest.CollisionType) == 0)
		return false;

	bool retval = false;

	// Check each line segment against the ray
	float fraction = 1.0F;
	for (unsigned int index = 1; index < (unsigned int)PointLocations.Count(); index++)
	{
		Vector3 curr[2];
		Transform.mulVector3Array(&PointLocations[index - 1], curr, 2);
		LineSegClass line_seg(curr[0], curr[1]);

		Vector3 p0;
		Vector3 p1;
		if (raytest.Ray.Find_Intersection(line_seg, &p0, &fraction, &p1, NULL))
		{
			// Determine if the ray was close enough to this line to be considered intersecting
			float dist = (p0 - p1).Length();
			if (dist <= LineRenderer.Get_Width() && fraction >= 0 && fraction < raytest.Result->Fraction)
			{
				retval = true;
				break;
			}
		}
	}

	// Fill in the raytest structure if we were successfull
	if (retval)
	{
		raytest.Result->Fraction = fraction;
		raytest.Result->SurfaceType = SURFACE_TYPE_DEFAULT;
		raytest.CollidedRenderObj = this;
	}

	return retval;
}

